1	import React, { useState, useCallback, useEffect, useMemo } from "react";
2	import { useSearchParams, useLocation, useNavigate } from "react-router-dom";
3	import { useQuery, useQueryClient } from "@tanstack/react-query";
4	import { useAuth } from "@/hooks/useAuth";
5	import { supabase } from "@/integrations/supabase/client";
6	import AppHeader from "@/components/AppHeader";
7	import AuthDialog from "@/components/AuthDialog";
8	import JobSidebar from "@/components/JobSidebar";
9	import JobDetailView from "@/components/JobDetailView";
10	import JobsOverviewCard from "@/components/JobsOverviewCard";
11	import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
12	import { Card, CardContent } from "@/components/ui/card";
13	import { Badge } from "@/components/ui/badge";
14	import { Button } from "@/components/ui/button";
15	import { Plus, Briefcase, FileText, Coins, CheckCircle2, ChevronRight, ChevronLeft } from "lucide-react";
16	import { format } from "date-fns";
17	import { toast } from "sonner";
18	import OnboardingWizard from "@/components/OnboardingWizard";
19	
20	export interface PastJob {
21	  id: string;
22	  title: string | null;
23	  job_description: string;
24	  status: string;
25	  created_at: string;
26	  resume_count: number;
27	  jd_analysis_json: any;
28	  dynamic_weights_json: Record<string, number> | null;
29	  inbox_email: string | null;
30	}
31	
32	export interface Result {
33	  id: string;
34	  resume_id: string;
35	  overall_score: number;
36	  missing_skills: string[];
37	  summary: string | null;
38	  interview_questions: any;
39	  filename: string;
40	  file_path: string | null;
41	  candidate_name: string | null;
42	  candidate_email?: string | null;
43	  candidate_phone?: string | null;
44	  candidate_location?: string | null;
45	  // Dynamic scoring fields
46	  hard_fit?: boolean;
47	  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
48	  confidence?: number;
49	  strengths_json?: string[];
50	  gaps_json?: string[];
51	  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string; matched_preferred?: string[]; missing_preferred?: string[] };
52	  matched_must_haves?: string[];
53	  missing_must_haves?: string[];
54	  scoring_version?: string;
55	  pending?: boolean;
56	  parsed_json?: any;
57	  assigned_to?: string | null;
58	}
59	
60	export interface ExistingResume {
61	  id: string;
62	  filename: string;
63	  file_path: string | null;
64	  candidate_name: string | null;
65	  created_at: string;
66	}
67	
68	type ViewMode = "dashboard" | "my-jobs" | "job-detail" | "new-job";
69	
70	const ONBOARDING_KEY = "rankora_onboarding_done";
71	
72	const Index = () => {
73	  const { user, profile } = useAuth();
74	  const [searchParams, setSearchParams] = useSearchParams();
75	  const location = useLocation();
76	  const navigate = useNavigate();
77	
78	  // Show onboarding wizard for first-time users
79	  const [showOnboarding, setShowOnboarding] = useState(() => {
80	    if (typeof window === "undefined") return false;
81	    return !localStorage.getItem(ONBOARDING_KEY);
82	  });
83	
84	  const completeOnboarding = useCallback(() => {
85	    localStorage.setItem(ONBOARDING_KEY, "1");
86	    setShowOnboarding(false);
87	  }, []);
88	
89	  const queryClient = useQueryClient();
90	
91	  const { data: pastJobs = [], isLoading: loadingPastJobs } = useQuery({
92	    queryKey: ["pastJobs", user?.id],
93	    queryFn: async () => {
94	      const { data: jobs } = await supabase
95	        .from("jobs")
96	        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
97	        .eq("user_id", user!.id)
98	        .order("created_at", { ascending: false })
99	        .limit(50);
100	      if (!jobs) return [];
101	      return jobs.map((j: any) => ({
102	        id: j.id,
103	        title: j.title,
104	        job_description: j.job_description,
105	        status: j.status,
106	        created_at: j.created_at,
107	        resume_count: j.resumes?.[0]?.count ?? 0,
108	        jd_analysis_json: j.jd_analysis_json,
109	        dynamic_weights_json: j.dynamic_weights_json,
110	        inbox_email: j.inbox_email ?? null,
111	      })) as PastJob[];
112	    },
113	    enabled: !!user,
114	    staleTime: 2 * 60 * 1000,
115	  });
116	
117	  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
118	  const [view, setView] = useState<ViewMode>(location.pathname === "/jobs" ? "my-jobs" : "dashboard");
119	  const [results, setResults] = useState<Result[]>([]);
120	  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
121	  const [authOpen, setAuthOpen] = useState(false);
122	
123	  const selectedJob = useMemo(() => pastJobs.find((j) => j.id === selectedJobId) ?? null, [pastJobs, selectedJobId]);
124	
125	  // Sync view with route path
126	  useEffect(() => {
127	    if (location.pathname === "/jobs") {
128	      setView("my-jobs");
129	      setSelectedJobId(null);
130	    }
131	  }, [location.pathname]);
132	
133	  // Handle URL params for deep linking
134	  useEffect(() => {
135	    const jobParam = searchParams.get("job");
136	    const newParam = searchParams.get("new");
137	
138	    if (jobParam && user) {
139	      loadJobData(jobParam);
140	      setSearchParams({}, { replace: true });
141	    } else if (newParam && user) {
142	      handleNewJob();
143	      setSearchParams({}, { replace: true });
144	    }
145	    // eslint-disable-next-line react-hooks/exhaustive-deps
146	  }, [searchParams, user]);
147	
148	  const loadJobData = async (jobId: string) => {
149	    setSelectedJobId(jobId);
150	    setView("job-detail");
151	    try {
152	      // Single query for all resume data (was 2 separate queries)
153	      const { data: allResumes } = await supabase
154	        .from("resumes")
155	        .select("id, filename, file_path, candidate_name, created_at, parsed_json")
156	        .eq("job_id", jobId)
157	        .order("created_at", { ascending: false });
158	
159	      const resumeData = allResumes ?? [];
160	      setExistingResumes(resumeData.map((r) => ({
161	        id: r.id, filename: r.filename, file_path: r.file_path,
162	        candidate_name: r.candidate_name, created_at: r.created_at,
163	      })));
164	
165	      if (resumeData.length === 0) {
166	        setResults([]);
167	        return;
168	      }
169	
170	      const resumeIds = resumeData.map((r) => r.id);
171	      const { data: resultData } = await supabase
172	        .from("results")
173	        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
174	        .in("resume_id", resumeIds);
175	
176	      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
177	      const allMerged: Result[] = (resultData ?? []).map((r: any) => {
178	        const resume = resumeMap.get(r.resume_id);
179	        const parsed = resume?.parsed_json as any;
180	        return {
181	          ...r,
182	          overall_score: r.overall_score ?? 0,
183	          missing_skills: r.missing_skills ?? [],
184	          filename: resume?.filename ?? "Unknown",
185	          file_path: resume?.file_path ?? null,
186	          candidate_name: resume?.candidate_name ?? null,
187	          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
188	          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
189	          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
190	          parsed_json: resume?.parsed_json ?? null,
191	        };
192	      });
193	      // Deduplicate by resume_id — keep highest scoring result per resume
194	      const deduped = new Map<string, Result>();
195	      for (const r of allMerged) {
196	        const existing = deduped.get(r.resume_id);
197	        if (!existing || r.overall_score > existing.overall_score) {
198	          deduped.set(r.resume_id, r);
199	        }
200	      }
201	      const merged = Array.from(deduped.values());
202	      merged.sort((a, b) => b.overall_score - a.overall_score);
203	      setResults(merged);
204	    } catch (err) {
205	      toast.error("Failed to load job data");
206	    }
207	  };
208	
209	  const handleNewJob = () => {
210	    setSelectedJobId(null);
211	    setView("new-job");
212	    setResults([]);
213	    setExistingResumes([]);
214	  };
215	
216	  const handleGoToDashboard = () => {
217	    setSelectedJobId(null);
218	    setView("dashboard");
219	    setResults([]);
220	    setExistingResumes([]);
221	    navigate("/", { replace: true });
222	  };
223	
224	  const handleGoToMyJobs = () => {
225	    setSelectedJobId(null);
226	    setView("my-jobs");
227	    setResults([]);
228	    setExistingResumes([]);
229	    navigate("/jobs", { replace: true });
230	  };
231	
232	  const handleJobCreated = (job: PastJob) => {
233	    queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) => [job, ...(prev ?? [])]);
234	    setSelectedJobId(job.id);
235	    loadJobData(job.id);
236	  };
237	
238	  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
239	    queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) =>
240	      (prev ?? []).map((j) => (j.id === jobId ? { ...j, ...updates } : j))
241	    );
242	  };
243	
244	  const handleDeleteJobs = async (jobIds: string[]) => {
245	    await supabase.from("jobs").delete().in("id", jobIds);
246	    queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) =>
247	      (prev ?? []).filter((j) => !jobIds.includes(j.id))
248	    );
249	  };
250	
251	  const requireAuth = useCallback(() => {
252	    if (!user) { setAuthOpen(true); return true; }
253	    return false;
254	  }, [user]);
255	
256	  return (
257	    <SidebarProvider className="h-svh overflow-hidden">
258	      <JobSidebar
259	        showDashboard={view === "dashboard"}
260	        showMyJobs={view === "my-jobs" || view === "job-detail"}
261	        onNewJob={handleNewJob}
262	        onDashboard={handleGoToDashboard}
263	        onMyJobs={handleGoToMyJobs}
264	        onAuthRequired={() => setAuthOpen(true)}
265	        isAuthenticated={!!user}
266	      />
267	
268	      <SidebarInset className="h-svh overflow-hidden bg-sidebar p-2 pl-0">
269	        <div className="h-full flex flex-col rounded-xl border bg-background overflow-hidden">
270	        <AppHeader />
271	        <div className="flex items-center h-10 px-4 md:hidden">
272	          <SidebarTrigger />
273	          <span className="ml-2 text-sm font-medium text-muted-foreground">Menu</span>
274	        </div>
275	        <div className="flex-1 overflow-y-auto">
276	
277	        {/* Dashboard view */}
278	        {view === "dashboard" && user ? (
279	          <main className="w-full px-6 sm:px-8 lg:px-10 py-8 space-y-6">
280	            {/* Hero Section — Greeting + Create Button */}
281	            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
282	              <div>
283	                <h1 className="text-2xl font-bold text-foreground">
284	                  Welcome back, {user.user_metadata?.full_name?.split(" ")[0] || user.email?.split("@")[0]}!
285	                </h1>
286	                <p className="text-sm text-muted-foreground mt-1">
287	                  Here's an overview of your hiring activity and insights.
288	                </p>
289	              </div>
290	              <Button className="gap-2" onClick={handleNewJob}>
291	                <Plus className="h-4 w-4" /> Create Job
292	              </Button>
293	            </div>
294	
295	            {/* Stats Cards */}
296	            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
297	              {[
298	                { label: "Total Jobs", value: pastJobs.length, icon: Briefcase, color: "bg-blue-100 text-blue-600" },
299	                { label: "Total Resumes", value: pastJobs.reduce((s, j) => s + j.resume_count, 0), icon: FileText, color: "bg-emerald-100 text-emerald-600" },
300	                { label: "Credits Left", value: (() => { const p = profile; if (!p) return 0; const s = (p.subscription_credits ?? 0) + (p.topup_credits ?? 0) + (p.bonus_credits ?? 0); return s > 0 ? s : (p.credits ?? 0); })(), icon: Coins, color: "bg-amber-100 text-amber-600" },
301	                { label: "Jobs Completed", value: pastJobs.filter(j => j.status === "completed").length, icon: CheckCircle2, color: "bg-violet-100 text-violet-600" },
302	              ].map((s) => (
303	                <Card key={s.label} className="border border-border/60 shadow-sm hover:shadow-md transition-shadow">
304	                  <CardContent className="px-5 py-4 flex items-center gap-4">
305	                    <div className={`h-11 w-11 rounded-xl flex items-center justify-center shrink-0 ${s.color}`}>
306	                      <s.icon className="h-5 w-5" />
307	                    </div>
308	                    <div>
309	                      <p className="text-2xl font-bold tabular-nums text-foreground">{s.value}</p>
310	                      <p className="text-xs text-muted-foreground font-medium">{s.label}</p>
311	                    </div>
312	                  </CardContent>
313	                </Card>
314	              ))}
315	            </div>
316	
317	            {/* Recent Jobs */}
318	            {pastJobs.length > 0 && (
319	              <div className="space-y-3">
320	                <div className="flex items-center justify-between">
321	                  <h2 className="text-sm font-semibold text-foreground">Recent Jobs</h2>
322	                  <button onClick={handleGoToMyJobs} className="text-xs font-medium text-primary hover:text-primary/80 transition-colors">
323	                    View All Jobs →
324	                  </button>
325	                </div>
326	                <div className="grid gap-3">
327	                  {pastJobs.slice(0, 5).map((job) => (
328	                    <Card key={job.id} className="cursor-pointer hover:shadow-md transition-all border border-border/60" onClick={() => loadJobData(job.id)}>
329	                      <CardContent className="px-5 py-3.5 flex items-center justify-between">
330	                        <div className="flex items-center gap-3 min-w-0">
331	                          <div className="h-9 w-9 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
332	                            <Briefcase className="h-4 w-4 text-primary" />
333	                          </div>
334	                          <div className="min-w-0">
335	                            <p className="text-sm font-medium text-foreground truncate">{job.title || "Untitled Job"}</p>
336	                            <p className="text-xs text-muted-foreground mt-0.5">
337	                              {job.resume_count} resume{job.resume_count !== 1 ? "s" : ""} · {format(new Date(job.created_at), "MMM d, yyyy")}
338	                            </p>
339	                          </div>
340	                        </div>
341	                        <div className="flex items-center gap-3 shrink-0">
342	                          <Badge
343	                            variant={job.status === "completed" ? "success" : job.status === "pending" || job.status === "processing" ? "warning" : "outline"}
344	                            className="text-xs"
345	                          >
346	                            {job.status.charAt(0).toUpperCase() + job.status.slice(1)}
347	                          </Badge>
348	                          <ChevronRight className="h-4 w-4 text-muted-foreground" />
349	                        </div>
350	                      </CardContent>
351	                    </Card>
352	                  ))}
353	                </div>
354	              </div>
355	            )}
356	
357	            {/* Getting started guide — show only for new users */}
358	            {pastJobs.length === 0 && !loadingPastJobs && (
359	              <Card>
360	                <CardContent className="px-5 py-4 space-y-3">
361	                  <h2 className="text-sm font-medium text-foreground">Getting Started</h2>
362	                  <div className="space-y-2.5">
363	                    {[
364	                      { step: "1", text: "Click \"Create New Job\" and paste a job description" },
365	                      { step: "2", text: "Upload candidate resumes (PDF, DOCX, or forward via email)" },
366	                      { step: "3", text: "AI ranks all candidates with scores, strengths, and gaps" },
367	                    ].map((item) => (
368	                      <div key={item.step} className="flex items-start gap-3 text-sm">
369	                        <span className="h-5 w-5 rounded-full bg-primary text-primary-foreground text-xs font-bold flex items-center justify-center shrink-0 mt-0.5">{item.step}</span>
370	                        <span className="text-muted-foreground">{item.text}</span>
371	                      </div>
372	                    ))}
373	                  </div>
374	                </CardContent>
375	              </Card>
376	            )}
377	          </main>
378	        ) : view === "my-jobs" && user ? (
379	          /* My Jobs view — full management */
380	          <main className="w-full px-6 sm:px-8 lg:px-10 py-8 space-y-6">
381	            <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
382	              <div className="space-y-1">
383	                <h1 className="text-2xl font-bold text-foreground">My Jobs</h1>
384	                <p className="text-sm text-muted-foreground">Manage all your job postings.</p>
385	              </div>
386	              <Button className="gap-2 shrink-0" onClick={handleNewJob}>
387	                <Plus className="h-4 w-4" /> Create Job
388	              </Button>
389	            </div>
390	            <JobsOverviewCard jobs={pastJobs} loading={loadingPastJobs} onSelectJob={loadJobData} onDeleteJobs={handleDeleteJobs} />
391	          </main>
392	        ) : (
393	          <JobDetailView
394	            selectedJobId={selectedJobId}
395	            selectedJob={selectedJob}
396	            results={results}
397	            setResults={setResults}
398	            existingResumes={existingResumes}
399	            setExistingResumes={setExistingResumes}
400	            onJobCreated={handleJobCreated}
401	            onAuthRequired={() => setAuthOpen(true)}
402	            isAuthenticated={!!user}
403	            pastJobs={pastJobs}
404	            onJobUpdated={handleJobUpdated}
405	            onBack={handleGoToMyJobs}
406	          />
407	        )}
408	        </div>
409	        </div>
410	      </SidebarInset>
411	
412	      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
413	
414	      {user && showOnboarding && (
415	        <OnboardingWizard
416	          open={showOnboarding}
417	          onComplete={completeOnboarding}
418	          onCreateJob={() => { completeOnboarding(); handleNewJob(); }}
419	          onGoToTeam={() => { completeOnboarding(); navigate("/team"); }}
420	          userName={user.user_metadata?.full_name?.split(" ")[0] || user.email?.split("@")[0] || "there"}
421	        />
422	      )}
423	    </SidebarProvider>
424	  );
425	};
426	
427	export default Index;
428	
