1	import { useState } from "react";
2	import { useAuth } from "@/hooks/useAuth";
3	import { useTeam } from "@/hooks/useTeam";
4	import { supabase } from "@/integrations/supabase/client";
5	import SidebarLayout from "@/components/SidebarLayout";
6	import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
7	import { Button } from "@/components/ui/button";
8	import { Input } from "@/components/ui/input";
9	import { Label } from "@/components/ui/label";
10	import { Switch } from "@/components/ui/switch";
11	import { LogOut, Zap, MessageCircle } from "lucide-react";
12	import { toast } from "sonner";
13	import AvailabilitySettings from "@/components/AvailabilitySettings";
14	
15	
16	const Settings = () => {
17	  const { user, profile, signOut, refreshProfile } = useAuth();
18	  const { team } = useTeam();
19	  const autoRank = profile?.auto_rank_enabled ?? true;
20	  const [whatsappNumber, setWhatsappNumber] = useState<string>((profile as any)?.whatsapp_number ?? "");
21	  const [savingWhatsapp, setSavingWhatsapp] = useState(false);
22	
23	  const toggleAutoRank = async (enabled: boolean) => {
24	    if (!user) return;
25	    try {
26	      const { error } = await supabase
27	        .from("profiles")
28	        .update({ auto_rank_enabled: enabled } as any)
29	        .eq("user_id", user.id);
30	      if (error) throw error;
31	      await refreshProfile();
32	      toast.success(enabled ? "Auto-rank enabled" : "Auto-rank disabled");
33	    } catch {
34	      toast.error("Failed to update setting");
35	    }
36	  };
37	
38	  const saveWhatsappNumber = async () => {
39	    if (!user) return;
40	    setSavingWhatsapp(true);
41	    try {
42	      const { error } = await supabase
43	        .from("profiles")
44	        .update({ whatsapp_number: whatsappNumber.trim() || null } as any)
45	        .eq("user_id", user.id);
46	      if (error) throw error;
47	      await refreshProfile();
48	      toast.success("WhatsApp number saved");
49	    } catch {
50	      toast.error("Failed to save WhatsApp number");
51	    } finally {
52	      setSavingWhatsapp(false);
53	    }
54	  };
55	
56	  return (
57	    <SidebarLayout>
58	      <main className="w-full px-6 sm:px-8 lg:px-10 py-8">
59	        <h1 className="text-2xl font-bold text-foreground mb-6">Settings</h1>
60	        <div className="space-y-6">
61	          {/* Auto-rank toggle */}
62	          <Card className="border border-border/60 shadow-sm">
63	            <CardHeader className="pb-3">
64	              <div className="flex items-center justify-between">
65	                <div className="flex items-center gap-2">
66	                  <Zap className="h-5 w-5 text-primary" />
67	                  <CardTitle className="text-sm font-semibold">Auto-rank resumes</CardTitle>
68	                </div>
69	                <Switch checked={autoRank} onCheckedChange={toggleAutoRank} />
70	              </div>
71	              <CardDescription>
72	                {autoRank
73	                  ? "Resumes are automatically scored after upload. Credits are used immediately."
74	                  : "Resumes stay as Pending after upload. You choose when to rank and spend credits."}
75	              </CardDescription>
76	            </CardHeader>
77	          </Card>
78	
79	          {/* WhatsApp number */}
80	          <Card className="border border-border/60 shadow-sm">
81	            <CardHeader className="pb-3">
82	              <div className="flex items-center gap-2">
83	                <MessageCircle className="h-5 w-5 text-[#25D366]" />
84	                <CardTitle className="text-sm font-semibold">WhatsApp Number</CardTitle>
85	              </div>
86	              <CardDescription>
87	                Your WhatsApp number is pre-filled when messaging candidates. Include country code (e.g. +1 555 123 4567).
88	              </CardDescription>
89	            </CardHeader>
90	            <CardContent>
91	              <div className="flex items-center gap-2">
92	                <div className="flex-1">
93	                  <Label htmlFor="whatsapp-number" className="sr-only">WhatsApp Number</Label>
94	                  <Input
95	                    id="whatsapp-number"
96	                    value={whatsappNumber}
97	                    onChange={(e) => setWhatsappNumber(e.target.value)}
98	                    placeholder="+1 555 123 4567"
99	                    type="tel"
100	                  />
101	                </div>
102	                <Button
103	                  size="sm"
104	                  onClick={saveWhatsappNumber}
105	                  disabled={savingWhatsapp}
